import { generateStars } from '@shared/galaxy/stars';
import { generateSystem } from '@shared/galaxy/system';
import { padsForSystem } from '@shared/world/pads';
import { hazardsFor } from '@shared/world/hazards';

const seed = 'DRIFT-SEED-0001';
const stars = generateStars(seed);
let firstStorm: { planetId: string; pos: { x: number; y: number; z: number }; radius: number } | null = null;
let firstStormSystem: string | null = null;
let firstPad: { planetId: string } | null = null;
let firstPadSystem: string | null = null;
for (const star of stars) {
  const system = generateSystem(seed, star.id);
  const storm = hazardsFor(seed, system).find((h) => h.kind === 'storm');
  if (storm && !firstStorm) {
    firstStorm = storm as typeof firstStorm & object;
    firstStormSystem = system.systemId;
  }
  const pad = padsForSystem(seed, system).find((p) => {
    const pl = system.planets.find((x) => x.id === p.planetId);
    return pl?.landable && pl?.hasAtmosphere;
  });
  if (pad && !firstPad) {
    firstPad = { planetId: pad.planetId };
    firstPadSystem = system.systemId;
  }
  if (firstStorm && firstPad) break;
}
console.log('firstStormSystem', firstStormSystem, firstStorm);
console.log('firstPadSystem', firstPadSystem, firstPad);
const padSys = generateSystem(seed, firstPadSystem!);
const padStorms = hazardsFor(seed, padSys).filter((h) => h.kind === 'storm' && h.planetId === firstPad!.planetId);
console.log('storms on firstPad planet:', JSON.stringify(padStorms));
const stormSys = generateSystem(seed, firstStormSystem!);
const stormPlanet = stormSys.planets.find((p) => p.id === firstStorm!.planetId);
console.log('storm planet landable/atmo:', stormPlanet?.landable, stormPlanet?.hasAtmosphere);
const stormPads = padsForSystem(seed, stormSys).filter((p) => p.planetId === firstStorm!.planetId);
